                margin={{ left: 4, right: 12, top: 8, bottom: 48 }}
              >
                <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                <XAxis
                  dataKey="metric"
                  tick={{ fontSize: 10 }}
                  interval={0}
