                <Bar dataKey="July" fill={PRIOR} radius={[4, 4, 0, 0]} />
                <Bar dataKey="August" fill={HEAT} radius={[4, 4, 0, 0]} />
              </BarChart>
            </ResponsiveContainer>
          </div>
        </ChartCard>
      )}

      {panel === "fed" && (
        <ChartCard
          title="Bank book still on 2026Q1 Fed SA ??? carried path"
          subtitle="No newer charge-off/delinquency SA vintage; cards 3.84%, CRE delinq 1.56%, CRE CO 0.17%"
        >
          <div className="h-[380px] w-full min-w-0">
            <ResponsiveContainer width="100%" height="100%">
              <LineChart
                data={FED_SA_PATH}
                margin={{ left: 4, right: 12, top: 8, bottom: 8 }}
              >
                <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                <XAxis dataKey="label" tick={{ fontSize: 11 }} />
                <YAxis
                  tick={{ fontSize: 11 }}
                  tickFormatter={(v) => `${v}%`}
                />
                <Tooltip
                  formatter={(value, name) => [
                    fmtPct(Number(value)),
                    String(name),
                  ]}
                />
                <Line
                  type="monotone"
                  dataKey="creDelinq"
                  name="CRE delinq"
                  stroke={CRE}
                  strokeWidth={2.5}
                  dot={{ r: 3 }}
                />
                <Line
                  type="monotone"
                  dataKey="creChargeOff"
                  name="CRE charge-off"
                  stroke={CRE}
                  strokeWidth={2}
                  strokeDasharray="5 4"
                  dot={{ r: 2 }}
                />
                <Line
                  type="monotone"
                  dataKey="cardsChargeOff"
                  name="Cards charge-off"
                  stroke={CARDS}
                  strokeWidth={2.5}
                  dot={{ r: 3 }}
                />
                <Line
                  type="monotone"
                  dataKey="ciChargeOff"
                  name="C&I charge-off"
                  stroke={CI}
                  strokeWidth={2}
                  dot={{ r: 2 }}
                />
              </LineChart>
            </ResponsiveContainer>
          </div>
        </ChartCard>
      )}

      {panel === "map" && (
        <ChartCard
          title="Two ledgers ??? bank SA rates vs CMBS delinquency"
          subtitle="CMBS points sit far right on delinquency; bank CRE stays high-past-due / low-loss"
        >
          <div className="h-[360px] w-full min-w-0">
            <ResponsiveContainer width="100%" height="100%">
              <ScatterChart margin={{ left: 8, right: 16, top: 12, bottom: 8 }}>
                <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                <XAxis
                  type="number"
                  dataKey="delinquency"
                  name="Delinquency"
                  unit="%"
                  tick={{ fontSize: 11 }}
                  domain={[0, 13]}
                />
                <YAxis
                  type="number"
                  dataKey="chargeOffPlot"
                  name="Charge-off"
                  tick={{ fontSize: 11 }}
                  domain={[-0.1, 4.2]}
                  tickFormatter={(v) => `${v}%`}
                />
                <ZAxis range={[90, 90]} />
                <Tooltip
                  cursor={{ strokeDasharray: "3 3" }}
                  formatter={(value, name, item) => {
                    const row = item?.payload as (typeof mapRows)[0] | undefined;
                    if (row?.isCmbs && name === "chargeOffPlot")
                      return ["n/a (CMBS)", "Charge-off"];
                    if (name === "delinquency")
                      return [fmtPct(Number(value)), "Delinquency"];
                    return [fmtPct(Number(value)), "Charge-off"];
                  }}
                  labelFormatter={(_, payload) => {
                    const row = payload?.[0]?.payload as
                      | (typeof mapRows)[0]
                      | undefined;
                    return row?.short ?? "";
                  }}
                />
                <Scatter data={mapRows} fill={CRE}>
                  {mapRows.map((r) => (
                    <Cell
                      key={r.short}
                      fill={
                        r.isCmbs
                          ? CMBS
                          : r.short.includes("Cards")
                            ? CARDS
                            : CRE
                      }
                    />
                  ))}
                </Scatter>
              </ScatterChart>
            </ResponsiveContainer>
          </div>
        </ChartCard>
      )}

      <div className="rounded-lg border border-slate-200 bg-slate-50 px-4 py-3 text-xs text-slate-600">
        <p className="font-medium text-slate-700">Sources</p>
        <p className="mt-1">{SOURCE_NOTE}</p>
        <ul className="mt-2 flex flex-wrap gap-x-4 gap-y-1">
          {SOURCES.map((s) => (
            <li key={s.url}>
              <a
                href={s.url}
                className="text-sky-700 underline-offset-2 hover:underline"
              >
                {s.label}
              </a>
            </li>
          ))}
        </ul>
      </div>
    </div>
  );
}

