"use client";

import { useMemo, useState } from "react";
import {
  Bar,
  BarChart,
  CartesianGrid,
  Cell,
  Line,
  LineChart,
  Pie,
  PieChart,
  ReferenceLine,
  ResponsiveContainer,
  Scatter,
  ScatterChart,
  XAxis,
  YAxis,
  ZAxis,
} from "recharts";
import { Tooltip } from "@/components/charts/SortedTooltip";
import {
  COHORT_COMPARE,
  DIVERGENCE,
  DY_BANDS,
  FED_SA_PATH,
  HEADLINE,
  MATURITY_MIX,
  SOURCE_NOTE,
  SOURCES,
  STRESS_MAP,
  VINTAGE_METERS,
  divergenceSorted,
  fmtBn,
  fmtBp,
  fmtMn,
  fmtPct,
  fmtPp,
  meterDeltasSorted,
} from "@/data/bank-commercial-credit-update-202608-data";

// viz-types: signed ?? bars, delinq??SS divergence scatter, maturity mix bars, DY risk pie, Jul???Aug cohort grouped bars, Fed dual-line, stress scatter | layout: canvas
// viz-plan: Aug meters; divergence scatter; maturity+DY; cohort compare; carried Fed SA; bank??CMBS map; panel + quadrant + book controls

type Panel = "meters" | "diverge" | "maturity" | "cohort" | "fed" | "map";
type Quadrant = "all" | "delinqUpSsDown" | "bothUp" | "ssUp";
type MapBook = "all" | "bank" | "cmbs";

const CRE = "#0ea5e9";
const CARDS = "#f59e0b";
const CI = "#a78bfa";
const COOL = "#14b8a6";
const HEAT = "#f43f5e";
const PRIOR = "#94a3b8";
const CMBS = "#e11d48";
const OFFICE = "#0369a1";
const RETAIL = "#c026d3";
const MF = "#38bdf8";
const LODGE = "#f97316";

const DY_COLORS = ["#0f766e", "#f59e0b", "#e11d48"];

function ChartCard({
  title,
  subtitle,
  children,
}: {
  title: string;
  subtitle?: string;
  children: React.ReactNode;
}) {
  return (
    <div className="w-full min-w-0 overflow-hidden rounded-xl border border-slate-200 bg-white shadow-sm">
      <div className="border-b border-slate-100 bg-slate-50 px-5 py-4">
        <h3 className="text-lg font-bold text-slate-900">{title}</h3>
        {subtitle && <p className="mt-1 text-sm text-slate-500">{subtitle}</p>}
      </div>
      <div className="p-4 sm:p-6">{children}</div>
    </div>
  );
}

function ToggleGroup<T extends string>({
  label,
  value,
  options,
  onChange,
}: {
  label: string;
  value: T;
  options: { id: T; label: string }[];
  onChange: (v: T) => void;
}) {
  return (
    <div className="flex flex-wrap items-center gap-2">
      <span className="text-xs font-semibold uppercase tracking-wide text-slate-500">
        {label}
      </span>
      {options.map((o) => {
        const on = o.id === value;
        return (
          <button
            key={o.id}
            type="button"
            onClick={() => onChange(o.id)}
            className={`rounded-md px-3 py-1.5 text-xs font-semibold transition ${
              on
                ? "bg-slate-900 text-white shadow-sm"
                : "bg-slate-100 text-slate-600 hover:bg-slate-200"
            }`}
          >
            {o.label}
          </button>
        );
      })}
    </div>
  );
}

function fillForMeter(delta: number, unit: string) {
  if (unit === "bn" || unit === "mn") return delta > 0 ? HEAT : COOL;
  if (delta < -0.05) return COOL;
  if (delta > 0.05) return HEAT;
  return PRIOR;
}

function propColor(id: string) {
  if (id === "office") return OFFICE;
  if (id === "retail") return RETAIL;
  if (id === "multifamily") return MF;
  if (id === "lodging") return LODGE;
  if (id === "overall") return CMBS;
  return PRIOR;
}

export function BankCommercialCreditUpdate202608Dashboard() {
  const [panel, setPanel] = useState<Panel>("meters");
