            onChange={setQuadrant}
            options={[
              { id: "all", label: "All" },
              { id: "delinqUpSsDown", label: "Delinq??? SS???" },
              { id: "bothUp", label: "Both ???" },
              { id: "ssUp", label: "SS ???" },
            ]}
          />
        )}
        {panel === "map" && (
          <ToggleGroup
            label="Book"
            value={mapBook}
            onChange={setMapBook}
            options={[
              { id: "all", label: "All" },
              { id: "bank", label: "Bank SA" },
