                />
                <Line
                  type="monotone"
                  dataKey="creDelinq"
                  name="CRE delinq"
                  stroke={CRE}
                  strokeWidth={2.5}
                  dot={{ r: 3 }}
                />
                <Line
                  type="monotone"
                  dataKey="creChargeOff"
                  name="CRE charge-off"
                  stroke={CRE}
                  strokeWidth={2}
                  strokeDasharray="5 4"
                  dot={{ r: 2 }}
