                <Line
                  type="monotone"
                  dataKey="cardsChargeOff"
                  name="Cards charge-off"
                  stroke={CARDS}
                  strokeWidth={2.5}
                  dot={{ r: 3 }}
                />
                <Line
                  type="monotone"
                  dataKey="ciChargeOff"
                  name="C&I charge-off"
                  stroke={CI}
                  strokeWidth={2}
                  dot={{ r: 2 }}
                />
              </LineChart>
            </ResponsiveContainer>
          </div>
        </ChartCard>
      )}

      {panel === "map" && (
        <ChartCard
          title="Two ledgers ??? bank SA rates vs CMBS delinquency"
          subtitle="CMBS points sit far right on delinquency; bank CRE stays high-past-due / low-loss"
        >
          <div className="h-[360px] w-full min-w-0">
            <ResponsiveContainer width="100%" height="100%">
              <ScatterChart margin={{ left: 8, right: 16, top: 12, bottom: 8 }}>
                <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                <XAxis
                  type="number"
                  dataKey="delinquency"
                  name="Delinquency"
                  unit="%"
                  tick={{ fontSize: 11 }}
                  domain={[0, 13]}
                />
                <YAxis
                  type="number"
                  dataKey="chargeOffPlot"
                  name="Charge-off"
                  tick={{ fontSize: 11 }}
                  domain={[-0.1, 4.2]}
                  tickFormatter={(v) => `${v}%`}
                />
                <ZAxis range={[90, 90]} />
                <Tooltip
                  cursor={{ strokeDasharray: "3 3" }}
                  formatter={(value, name, item) => {
                    const row = item?.payload as (typeof mapRows)[0] | undefined;
                    if (row?.isCmbs && name === "chargeOffPlot")
                      return ["n/a (CMBS)", "Charge-off"];
